// Compare each site's result with its last known state and only emit
// an alert when a site goes down or comes back up.
const state = $getWorkflowStaticData('global');
state.down = state.down || {};
const domains = $('Read domains').all();
const toMessage = (e) => (typeof e === 'string' ? e : (e?.message || JSON.stringify(e)));
const alerts = [];

$input.all().forEach((item, i) => {
  const domain = String(domains[i]?.json.Domain ?? '').trim().toLowerCase();
  const j = item.json;
  let problem = null;
  let eventType = null;
  if (j.error) {
    problem = toMessage(j.error);
    eventType = 'SITE_UNREACHABLE';
  } else if (j.statusCode >= 400) {
    problem = 'HTTP ' + j.statusCode + ' ' + (j.statusMessage || '');
    eventType = 'HTTP_' + j.statusCode;
  }

  if (problem && !state.down[domain]) {
    state.down[domain] = new Date().toISOString();
    alerts.push({ json: { domain, event_type: eventType, details: 'Scheduled check failed: ' + problem, source: 'n8n_scheduled_monitor', severity_hint: 'unknown' } });
  } else if (!problem && state.down[domain]) {
    alerts.push({ json: { domain, event_type: 'RECOVERED', details: 'Scheduled check is healthy again (HTTP ' + j.statusCode + ') after failing since ' + state.down[domain] + '. Verify and resolve if appropriate.', source: 'n8n_scheduled_monitor', severity_hint: 'unknown' } });
    delete state.down[domain];
  }
});

return alerts;
